// ZIP code → congressional district(s), entirely on the device, from the table generated by
// scripts/build-zip-districts.mjs (Census ZCTA-to-district relationship file). No network.

import { ZIP_DISTRICTS, ZIP_DISTRICTS_CONGRESS } from '@/data/zip-districts';
import type { District, LookupResult } from '@/lib/district-lookup';

export type ZipTable = { congress: number; entries: string };

const BUNDLED: ZipTable = { congress: ZIP_DISTRICTS_CONGRESS, entries: ZIP_DISTRICTS };

/** "12345" or "12345-6789" (spaces allowed around it) → "12345"; anything else → null. */
export function parseZip(input: string): string | null {
  const match = /^\s*(\d{5})(?:-?\d{4})?\s*$/.exec(input);
  return match ? match[1] : null;
}

// Parsed once per table, on first use, so app start-up doesn't pay for it.
const parsedTables = new WeakMap<ZipTable, Map<string, string>>();

function seatsByZip(table: ZipTable): Map<string, string> {
  let map = parsedTables.get(table);
  if (!map) {
    map = new Map();
    for (const entry of table.entries.split(';')) {
      if (entry.length > 5) map.set(entry.slice(0, 5), entry.slice(5));
    }
    parsedTables.set(table, map);
  }
  return map;
}

/** "TX18" → { state: 'TX', district: 18 }; "WY0" → at-large / delegate. */
function parseSeat(seat: string, congress: number): District | null {
  const match = /^([A-Z]{2})(\d+)$/.exec(seat);
  return match ? { state: match[1], district: Number(match[2]), congress } : null;
}

/**
 * The seat(s) for a 5-digit ZIP, from a table for `targetCongress`. A ZIP in several
 * districts returns `ambiguous` with every one of them as `choices`, in district order;
 * it never picks one.
 */
export function lookupZip(zip: string, targetCongress: number, table: ZipTable = BUNDLED): LookupResult {
  if (table.congress !== targetCongress) return { ok: false, error: 'zipNotUpdated' };
  const seats = seatsByZip(table).get(zip);
  if (!seats) return { ok: false, error: 'notFound' };
  const districts = seats
    .split(',')
    .map((seat) => parseSeat(seat, table.congress))
    .filter((d): d is District => d !== null);
  if (districts.length === 0) return { ok: false, error: 'notFound' };
  if (districts.length === 1) return { ok: true, district: districts[0] };
  return { ok: false, error: 'ambiguous', choices: districts };
}
